int main() {
    uint32_t data[9];
    while (scanf("%u", &data[0]) == 1) {
        for (int i = 1; i < 9; i++) {
            scanf("%u", &data[i]);
        }

        // Check checksum: sum of first 8 modulo 2^32 should equal the ninth
        uint32_t sum = 0;
        for (int i = 0; i < 8; i++) {
            sum += data[i];
        }
        if (sum != data[8]) {
            printf("0\n");
            continue;
        }

        // The key is the bit that was flipped: 
        // If LSB of each encrypted value is the same as original, key bit is 0
        // If LSB is flipped, key bit is 1
        // Since encryption flips all bits if key bit is 1, we can check the LSB pattern
        // The original data's LSBs should be consistent: either all match or all flipped
        // Since the original data is unknown, we deduce key from the fact that
        // the checksum condition must hold for the original data as well.
        // For the encryption: encrypted = original XOR (key_bit ? 0xFFFFFFFF : 0)
        // So original = encrypted XOR (key_bit ? 0xFFFFFFFF : 0)
        // The checksum condition for original: sum(original[0..7]) == original[8]
        // We try both key_bit = 0 and key_bit = 1
        uint32_t key = 0;
        int found = 0;

        // Try key_bit = 0
        uint32_t orig0[9];
        for (int i = 0; i < 9; i++) orig0[i] = data[i];
        uint32_t sum0 = 0;
        for (int i = 0; i < 8; i++) sum0 += orig0[i];
        if (sum0 == orig0[8]) {
            key = 0;
            found = 1;
        }

        // Try key_bit = 1 (flip all bits)
        if (!found) {
            uint32_t orig1[9];
            for (int i = 0; i < 9; i++) orig1[i] = ~data[i];
            uint32_t sum1 = 0;
            for (int i = 0; i < 8; i++) sum1 += orig1[i];
            if (sum1 == orig1[8]) {
                key = 1;
                found = 1;
            }
        }

        if (!found) {
            printf("0\n");
        } else {
            printf("%u\n", key);
        }
    }
    return 0;
