int main(void) {
    uint32_t a[9];

    while (1) {
        int ok = 1;
        for (int i = 0; i < 9; i++) {
            unsigned long long x;
            if (scanf("%llu", &x) != 1) {
                ok = 0;
                break;
            }
            a[i] = (uint32_t)x;
        }
        if (!ok) break;

        uint32_t sum = 0;
        for (int i = 0; i < 8; i++) sum += a[i];

        /* 
           Encryption is bit-flipping by a 32-bit key k:
             enc(x) = x ^ k
           The 9th encrypted integer is checksum of the first 8 plaintext integers.

           Using only least significant bits:
             Let pi = lsb(plaintext_i), ci = lsb(cipher_i), ki = lsb(k).
             Then pi = ci ^ ki.
             Since checksum plaintext lsb equals parity of first 8 plaintext lsbs,
             we need:
               p8 = p0 ^ p1 ^ ... ^ p7
             i.e.
               (c8 ^ k) = (c0 ^ k) ^ ... ^ (c7 ^ k)
           Because k appears 8 times on RHS, it cancels there:
               c8 ^ k = c0 ^ c1 ^ ... ^ c7
               k = c8 ^ c0 ^ c1 ^ ... ^ c7

           So the least significant bit of the key is determined by XOR of LSBs
           of all 9 encrypted values. The standard bit-flipping scheme uses the
           same bit for all positions, hence the key is either all 0s or all 1s.
        */

        uint32_t lsb = 0;
        for (int i = 0; i < 9; i++) lsb ^= (a[i] & 1u);

        uint32_t key = lsb ? 0xFFFFFFFFu : 0x00000000u;

        printf("%u\n", key);
    }

    return 0;
}

