public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            long[] a = new long[9];
            long first = fs.nextLong();
            if (first == Long.MIN_VALUE) break;
            a[0] = first;

            for (int i = 1; i < 9; i++) {
                long v = fs.nextLong();
                if (v == Long.MIN_VALUE) return;
                a[i] = v;
            }

            int key = 0;

            // For each bit independently:
            // checksum bit = XOR of first 8 bits + carry-in at that bit.
            // Flipping a bit in all 9 numbers toggles parity of first 8 by 0 (even count)
            // and toggles checksum bit by 1, so whether equality holds changes.
            //
            // Hence for each bit, exactly one of:
            //   encrypted data already satisfies checksum relation -> key bit = 0
            //   encrypted data fails checksum relation         -> key bit = 1
            //
            // We determine this by checking the true sum modulo 2^32.
            long sum = 0;
            for (int i = 0; i < 8; i++) {
                sum = (sum + (a[i] & 0xFFFFFFFFL)) & 0xFFFFFFFFL;
            }
            long chk = a[8] & 0xFFFFFFFFL;

            // If numbers were encrypted by XOR with a 32-bit key applied to all 9 values,
            // then the key is exactly the bitmask where current checksum comparison fails.
            // Since the checksum relation is on the whole 32-bit sum, this means:
            //   decrypted checksum = sum(decrypted first 8) mod 2^32
            // Trying all bits independently is equivalent to:
            //   key = current_checksum XOR current_sum
            key = (int)((chk ^ sum) & 0xFFFFFFFFL);

            out.append(key).append('\n');
        }

        System.out.print(out.toString());
    }
}

