#include <bits/stdc++.h>
using namespace std;

/*
The statement is incomplete in the prompt we received, but the intended task is
the classic "find the 32-bit XOR key from 9 encrypted 32-bit integers" where:

- There are 9 encrypted 32-bit unsigned integers per dataset.
- The first 8 are data values.
- The 9th is a checksum and, after decryption, must equal
      (sum of first 8 decrypted values) mod 2^32.
- Encryption/decryption is by XOR with the same 32-bit key.
- The key is determined bit-by-bit using the checksum condition.
- The mention about the least significant bit hints at deriving each bit
  independently with carry propagation.

Let plaintext values be p[i], ciphertext values c[i], and key k.
Then p[i] = c[i] XOR k.

We need:
    p[8] == sum(p[0..7]) mod 2^32

For each bit position b, let:
    x_i = bit b of c[i]
    k_b = bit b of k
Then plaintext bit at position b is x_i XOR k_b.

Binary addition with carry allows determining k bit-by-bit:
For bit b, if carry into this bit is carry, then
    sum_{i=0..7}(x_i XOR k_b) + carry
has output bit equal to (x_8 XOR k_b),
and produces next carry.

Try k_b = 0 or 1; exactly one should be consistent for valid data.
Proceed from bit 0 to 31.

Input format is also not fully given, so we support the common style:
read all unsigned 32-bit integers from stdin; every 9 numbers form one dataset.
For each dataset output the key as an unsigned 32-bit integer.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<uint32_t> a;
    unsigned long long v;
    while (cin >> v) a.push_back((uint32_t)v);

    int m = (int)a.size();
    if (m % 9 != 0) return 0;

    for (int ds = 0; ds < m; ds += 9) {
        uint32_t c[9];
        for (int i = 0; i < 9; ++i) c[i] = a[ds + i];

        uint32_t key = 0;
        unsigned long long carry = 0;

        for (int b = 0; b < 32; ++b) {
            int bits[9];
            for (int i = 0; i < 9; ++i) bits[i] = (c[i] >> b) & 1u;

            bool found = false;
            for (int kb = 0; kb <= 1; ++kb) {
                int sumBits = 0;
                for (int i = 0; i < 8; ++i) sumBits += (bits[i] ^ kb);

                unsigned long long total = sumBits + carry;
                int outBit = (int)(total & 1ull);
                unsigned long long nextCarry = total >> 1;

                if (outBit == (bits[8] ^ kb)) {
                    if (kb) key |= (1u << b);
                    carry = nextCarry;
                    found = true;
                    break;
                }
            }

            // If malformed input causes no valid bit, default to 0-path.
            if (!found) {
                int sumBits = 0;
                for (int i = 0; i < 8; ++i) sumBits += bits[i];
                unsigned long long total = sumBits + carry;
                carry = total >> 1;
            }
        }

        cout << key << '\n';
    }

    return 0;
}

