def solve(encrypted):
    e = encrypted  # 9 values
    MOD = 2**32

    # Find key such that sum(e[i]^key for i in 0..7) mod 2^32 == e[8]^key
    # Try bit by bit
    candidates = [0]

    for bit in range(32):
        new_candidates = []
        mask = (1 << (bit + 1)) - 1
        for c in candidates:
            for b in [0, 1]:
                key = c | (b << bit)
                vals = [(e[i] ^ key) & mask for i in range(8)]
                s = sum(vals) & mask
                target = (e[8] ^ key) & mask
                if s == target:
                    new_candidates.append(key)
        candidates = new_candidates

    return candidates

